CREATE OR REPLACE FUNCTION public.normalize_phone(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  d text;
begin
  if p is null then
    return null;
  end if;
  d := regexp_replace(p, '[^0-9]', '', 'g');
  if d = '' then
    return '';
  end if;
  if d like '0084%' and length(d) >= 13 then
    d := '0' || substr(d, 5);
  elsif d like '84%' and length(d) >= 11 then
    d := '0' || substr(d, 3);
  end if;
  if length(d) = 9 and left(d, 1) in ('3','5','7','8','9') then
    d := '0' || d;
  end if;
  if length(d) = 11 and left(d, 1) = '0' then
    d := case left(d, 4)
      when '0162' then '032' when '0163' then '033' when '0164' then '034' when '0165' then '035'
      when '0166' then '036' when '0167' then '037' when '0168' then '038' when '0169' then '039'
      when '0120' then '070' when '0121' then '079' when '0122' then '077' when '0126' then '076'
      when '0128' then '078' when '0123' then '083' when '0124' then '084' when '0125' then '085'
      when '0127' then '081' when '0129' then '082' when '0186' then '056' when '0188' then '058'
      when '0199' then '059'
      else left(d, 4)
    end || substr(d, 5);
  end if;
  return d;
end;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_normalize_facebook_identity(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'public'
AS $function$
DECLARE
  v_raw text := btrim(p_value);
  v_clean text;
  v_id text;
BEGIN
  IF v_raw = '' THEN RETURN ''; END IF;
  -- Numeric IDs are already canonical.
  IF v_raw ~ '^[0-9]+$' THEN RETURN v_raw; END IF;
  -- profile.php?id=... must be extracted before query removal.
  v_id := substring(lower(v_raw) FROM '[?&]id=([0-9]+)');
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  v_clean := regexp_replace(v_raw, '^(https?://)?((www|m|mbasic)\.)?facebook\.com/', '', 'i');
  v_clean := regexp_replace(v_clean, '[?#].*$', '');
  v_clean := regexp_replace(v_clean, '/+$', '');
  v_clean := regexp_replace(v_clean, '^(groups|people|pages)/', '', 'i');
  IF v_clean ~ '/' THEN
    -- /people/name/123 and /pages/name/123 use the final numeric component.
    v_id := substring(v_clean FROM '([0-9]+)$');
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
    v_clean := split_part(v_clean, '/', 1);
  END IF;
  RETURN lower(v_clean);
END;
$function$
